"""Mock wafer sort of a 25-wafer lot: the bin of every die of each wafer, in
the dies' order. Replace it with your tester's results (e.g. from its STDF
files)."""
import json

LOT = json.loads('["","","","","","","","","","","","","","","","","","","","","","","","",""]')


class LotTester:
    def __init__(self):
        self.k = 0

    def wafers(self):
        return len(LOT)

    def sort(self):
        """Bins of the next wafer, one per die (1 good, 2 IDDQ, 3 Vth, 4 functional, 5 continuity)."""
        bins = [int(b) for b in LOT[self.k]]
        self.k += 1
        return bins
